const docId = input.documentId;
if (!docId) return { error: 'No documentId provided' };
const res = await fetch(apiUrl + '/documents/' + docId, {
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
});
if (!res.ok) {
  const err = await res.text();
  return { error: 'Failed to fetch document: ' + res.status + ' ' + err };
}
const data = await res.json();
const doc = data.data || data;
return {
  documentId: String(doc._id),
  title: doc.title,
  content: doc.content,
  summary: doc.summary || '',
  type: doc.type,
  status: doc.status,
  tags: doc.tags || [],
  version: doc.version,
  groupId: doc.groupId ? String(doc.groupId) : null
};

const modeOverride = (trigger && trigger.mode) || '';
if (modeOverride === 'question' || modeOverride === 'edit') {
  return { intent: modeOverride, complexity: modeOverride === 'edit' ? 'moderate' : 'simple', override: true };
}

const instruction = (trigger && trigger.instruction) || '';
const lower = instruction.toLowerCase().trim();

const questionPatterns = /^(what|why|how|when|where|who|which|is |are |does |do |can |could |would |should |tell me|explain|describe|summarize|list |show me)/;
const hasQuestionMark = lower.includes('?');
const editPatterns = /\b(change|update|add|remove|delete|edit|rewrite|fix|improve|replace|insert|append|prepend|move|rename|modify|restructure|refactor|shorten|expand|simplify|translate|convert|merge|split|reformat)\b/;

let intent = 'question';
let complexity = 'simple';

if (questionPatterns.test(lower) || hasQuestionMark) {
  intent = 'question';
  complexity = 'simple';
} else if (editPatterns.test(lower)) {
  intent = 'edit';
  complexity = lower.length > 200 ? 'complex' : 'moderate';
} else {
  intent = lower.length > 100 ? 'edit' : 'question';
  complexity = intent === 'edit' ? 'moderate' : 'simple';
}

return { intent, complexity };

const out = (input && input.output) || {};
const result = (out.result && typeof out.result === 'object') ? out.result : {};
const answer = String(result.answer || out.summary || 'No answer was produced.');
const summary = String(result.summary || out.summary || answer.split('\n')[0].slice(0, 160));
const relevantSections = Array.isArray(result.relevantSections) ? result.relevantSections : [];
const followUps = Array.isArray(result.suggestedFollowUps) ? result.suggestedFollowUps : [];
const targetDocumentId = (trigger && trigger.documentId) || '';
const instruction = (trigger && trigger.instruction) || '';

let groupId = null;
if (targetDocumentId) {
  try {
    const docRes = await fetch(apiUrl + '/documents/' + targetDocumentId, {
      headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
    });
    if (docRes.ok) {
      const docData = await docRes.json();
      const doc = docData.data || docData;
      if (doc && doc.groupId) groupId = String(doc.groupId);
    }
  } catch (e) { /* ignore */ }
}

let content = answer.trim();
if (relevantSections.length > 0) {
  content += '\n\n---\n\n**Relevant sections:** ' + relevantSections.map(s => '_' + s + '_').join(', ');
}

const title = ('Answer: ' + (instruction || 'Document question')).slice(0, 200);

const body = {
  title,
  content,
  summary,
  type: 'output',
  status: 'approved',
  tags: ['ai-answer', 'document-assistant'],
  metadata: {
    autoGenerated: true,
    richAnswer: {
      answer: content,
      summary,
      relevantSections,
      followUps,
      sourceContext: 'document',
      sourceTargetId: targetDocumentId,
      sourceInstruction: instruction
    }
  }
};
if (groupId) body.groupId = groupId;

const createRes = await fetch(apiUrl + '/documents', {
  method: 'POST',
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
if (!createRes.ok) {
  const err = await createRes.text();
  return { error: 'Failed to create answer document: ' + createRes.status + ' ' + err, answer, summary, followUps };
}
const createData = await createRes.json();
const doc = createData.data || createData;

return {
  success: true,
  answer: content,
  summary,
  followUps,
  relevantSections,
  documentId: String(doc._id),
  documentTitle: doc.title,
  documentOperations: [{
    success: true,
    action: 'create',
    documentId: String(doc._id),
    title: doc.title
  }],
  richAnswer: {
    answer: content,
    summary,
    relevantSections,
    followUps,
    sourceContext: 'document',
    sourceTargetId: targetDocumentId,
    sourceInstruction: instruction,
    documentId: String(doc._id)
  }
};

const out = (input && input.output) || {};
const result = (out.result && typeof out.result === 'object') ? out.result : {};
const editSummary = String(result.editSummary || out.summary || 'Document updated');
const editDetails = String(result.editDetails || '');
const sectionsModified = Array.isArray(result.sectionsModified) ? result.sectionsModified : [];
const followUps = Array.isArray(result.suggestedFollowUps) ? result.suggestedFollowUps : [];
const targetDocumentId = (trigger && trigger.documentId) || '';
const instruction = (trigger && trigger.instruction) || '';

let groupId = null;
if (targetDocumentId) {
  try {
    const docRes = await fetch(apiUrl + '/documents/' + targetDocumentId, {
      headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' }
    });
    if (docRes.ok) {
      const docData = await docRes.json();
      const doc = docData.data || docData;
      if (doc && doc.groupId) groupId = String(doc.groupId);
    }
  } catch (e) { /* ignore */ }
}

let content = '## ' + editSummary + '\n\n';
if (editDetails) content += editDetails + '\n\n';
if (sectionsModified.length > 0) {
  content += '### Sections modified\n\n' + sectionsModified.map(s => '- ' + s).join('\n') + '\n';
}

const title = ('Edit: ' + (instruction || 'Document update')).slice(0, 200);

const body = {
  title,
  content,
  summary: editSummary,
  type: 'output',
  status: 'approved',
  tags: ['ai-edit', 'document-assistant'],
  metadata: {
    autoGenerated: true,
    richAnswer: {
      answer: content,
      summary: editSummary,
      followUps,
      sectionsModified,
      sourceContext: 'document',
      sourceTargetId: targetDocumentId,
      sourceInstruction: instruction
    }
  }
};
if (groupId) body.groupId = groupId;

const createRes = await fetch(apiUrl + '/documents', {
  method: 'POST',
  headers: { 'X-API-Key': apiKey, 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
if (!createRes.ok) {
  const err = await createRes.text();
  return { error: 'Failed to create edit summary document: ' + createRes.status + ' ' + err, editSummary, followUps };
}
const createData = await createRes.json();
const doc = createData.data || createData;

return {
  success: true,
  documentId: targetDocumentId,
  editSummary,
  followUps,
  sectionsModified,
  summaryDocumentId: String(doc._id),
  documentTitle: doc.title,
  documentOperations: [{
    success: true,
    action: 'create',
    documentId: String(doc._id),
    title: doc.title
  }],
  richAnswer: {
    answer: content,
    summary: editSummary,
    followUps,
    sectionsModified,
    sourceContext: 'document',
    sourceTargetId: targetDocumentId,
    sourceInstruction: instruction,
    documentId: String(doc._id)
  }
};
